import{_ as s,a0 as o,w as g,s as u,I as t,x as i,a1 as r,A as p,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Ring ：一個專注隱私，開源的 Skype 替代品 | LCTT x X-CMD","titleTemplate":false,"description":"Ring ：一個專注隱私，開源的 Skype 替代品 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ring ：一個專注隱私，開源的 Skype 替代品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ring ：一個專注隱私，開源的 Skype 替代品 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170622 Ring is a Privacy-Focused Open-Source Skype Alternative","title":"Ring ：一個專注隱私，開源的 Skype 替代品","tag":"201707","desc":""},"relativePath":"201707/20170622 Ring is a Privacy-Focused Open-Source Skype Alternative.md","filePath":"[post].md"}'),a={name:"201707/20170622 Ring is a Privacy-Focused Open-Source Skype Alternative.md"};function d(R,n,m,f,S,T){const e=o("Link");return g(),u("div",null,[n[24]||(n[24]=t("h1",{id:"ring-一個專注隱私-開源的-skype-替代品",tabindex:"-1"},[i("Ring ：一個專注隱私，開源的 Skype 替代品 "),t("a",{class:"header-anchor",href:"#ring-一個專注隱私-開源的-skype-替代品","aria-label":"Permalink to “Ring ：一個專注隱私，開源的 Skype 替代品”"},"​")],-1)),n[25]||(n[25]=t("p",null,[t("img",{src:"https://mintguide.org/uploads/posts/2017-06/thumbs/1498158697_screenshot-at-2017-06-22-12-08-39.png",alt:""})],-1)),t("p",null,[t("strong",null,[n[1]||(n[1]=i("如果你對 Linux 上的 Skype 進度不滿意，或者對即將",-1)),r(e,{href:"https://linux.cn/article-7606-1.html"},{default:p(()=>[...n[0]||(n[0]=[i("換代的、舊的（但是優秀的）Qt Skype 客户端",-1)])]),_:1}),n[2]||(n[2]=i("感到不快，這有一個 GNU 替代品叫 Ring。",-1))])]),n[26]||(n[26]=l("<p>GNU Ring 是一個跨平台、關注隱私的交流程序，它很快得到了 FOSS 以及安全圈的注意。</p><p>就像一個 <strong>Skype 的開源替代品</strong>，不用揹負微軟 VoIP 客户端的那些東西，Ring 不僅能夠做大多數 Skype 能夠做的，還能以安全、讓人放心的私密方式做到：</p><ul><li>語音電話</li><li>電話會議</li><li>視頻電話</li><li>即時通信</li></ul><p>所有這些功能也可以跨設備運行。你同伴使用的是使用 Windows 版 Ring 或者 Android 版 Ring 都不重要。只要他們在 Ring 上，你就能聯繫他們！</p><p>Ring 通過分佈式對等網絡工作。這意味着它不用依賴於一個大型集中式服務器以存儲你所有詳細信息、通話記錄和帳户信息。相反，該服務使用分佈式哈希表建立通信。</p>",5)),t("p",null,[r(e,{href:"https://ring.cx/"},{default:p(()=>[...n[3]||(n[3]=[i("Ring 網站",-1)])]),_:1}),n[4]||(n[4]=i("使用端到端加密的認證（sic）、使用 X.509 證書管理身份、並且基於 RSA/AES/DTLS/SRTP 技術。",-1))]),n[27]||(n[27]=t("h3",{id:"下載-linux-版-ring",tabindex:"-1"},[i("下載 Linux 版 Ring "),t("a",{class:"header-anchor",href:"#下載-linux-版-ring","aria-label":"Permalink to “下載 Linux 版 Ring”"},"​")],-1)),t("p",null,[n[6]||(n[6]=i("你可以從項目網站或者按照下面的安裝指導在 Ubuntu 上添加 Ring 的官方倉庫來",-1)),r(e,{href:"https://ring.cx/en/download/gnu-linux"},{default:p(()=>[...n[5]||(n[5]=[i("下載 Linux 版 Ring",-1)])]),_:1}),n[7]||(n[7]=i("。這裏有兩個版本的客户端：KDE 版本和 GNOME 版本。",-1))]),n[28]||(n[28]=t("p",null,"如果你運行的 Ubuntu 帶有 Unity 或者 GNOME Shell，就選擇 GNOME 版本。",-1)),t("p",null,[n[9]||(n[9]=i("如果你對安裝感到疑惑，項目網站上有一個一個",-1)),r(e,{href:"https://ring.cx/en/tutorials/gnu-linux#RingID"},{default:p(()=>[...n[8]||(n[8]=[i("手把手的教程",-1)])]),_:1}),n[10]||(n[10]=i("。",-1))]),n[29]||(n[29]=l('<p>官方網站上還有直接的 Windows、macOS 和 Android 版鏈接。</p><h4 id="在-ubuntu-上設置-ring" tabindex="-1">在 Ubuntu 上設置 Ring <a class="header-anchor" href="#在-ubuntu-上設置-ring" aria-label="Permalink to “在 Ubuntu 上設置 Ring”">​</a></h4><p>當你安裝完 Linux 版客户端後，你就能夠使用了：在開始打電話前，你只需註冊一個 Ring ID。</p><p>Ring 的註冊不同於 Skype、Telegram 和 WhatsApp 那樣。你<strong>不必</strong>綁定一個手機號或者郵箱。</p><p>取而代之的是 Ring 會要求你輸入一個用户名（你可以任意輸入），接着會分配你一個冗長的身份號碼。你需要給其他 Ring 用户發送這個身份號碼，那麼他們可以給你打電話。</p><p>要<strong>在 Ring 中打第一通電話</strong>，你需要主程序的搜索欄輸入聯繫人的 Ring ID，接着點擊電話按鈕撥打電話。</p><p>其他事情應該相對直接。你可以在其他設備上安裝 Ring 並用你的帳户驗證，這樣你就不會錯過任何一個電話（如果你在 Android 設備上安裝，你可以掃描二維碼來快速設置）。</p><p>Ring 的細節以及配置存儲你家目錄下的配置文件夾內的 <code>dring.yml</code> 中。</p><h3 id="ring-怎麼樣" tabindex="-1">Ring 怎麼樣？ <a class="header-anchor" href="#ring-怎麼樣" aria-label="Permalink to “Ring 怎麼樣？”">​</a></h3><p>這篇文章“垃圾”的部分是告訴你 Ring 怎麼樣：我不知道因為我不認識任何使用 Ring 的人。因此我沒有機會真正使用它。</p><p>我嘗試 Google 來查找 Ring 的評測，但是這是一個噩夢，因為程序的名字太普遍了（雖然我現在非常瞭解 Ring 視頻門鈴）。</p><p><em><strong>如果你已經使用 Ring 或者你能夠勸説至少一個你認識的人使用，那麼記得回來分享一下關於連接質量和性能。</strong></em></p><hr>',13)),t("p",null,[n[12]||(n[12]=i("via: ",-1)),r(e,{href:"https://mintguide.org/internet/795-ring-is-a-privacy-focused-open-source-skype-alternative.html"},{default:p(()=>[...n[11]||(n[11]=[i("https://mintguide.org/internet/795-ring-is-a-privacy-focused-open-source-skype-alternative.html",-1)])]),_:1})]),t("p",null,[n[16]||(n[16]=i("作者：",-1)),r(e,{href:"https://mintguide.org/user/fabiomorales9999/"},{default:p(()=>[...n[13]||(n[13]=[i("fabiomorales9999",-1)])]),_:1}),n[17]||(n[17]=i(" 譯者：",-1)),r(e,{href:"https://github.com/geekpi"},{default:p(()=>[...n[14]||(n[14]=[i("geekpi",-1)])]),_:1}),n[18]||(n[18]=i(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:p(()=>[...n[15]||(n[15]=[i("wxy",-1)])]),_:1})]),t("p",null,[n[21]||(n[21]=i("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...n[19]||(n[19]=[i("LCTT",-1)])]),_:1}),n[22]||(n[22]=i(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:p(()=>[...n[20]||(n[20]=[i("Linux中國",-1)])]),_:1}),n[23]||(n[23]=i(" 榮譽推出",-1))])])}const b=s(a,[["render",d]]);export{y as __pageData,b as default};
